description:
Write `public ref struct CsvFields` that walks the fields of one CSV line without allocating, so it can be used like this:

```csharp
var fields = new CsvFields("ada,36,,london");
while (fields.MoveNext(out ReadOnlySpan<char> field))
    Console.WriteLine($"[{field}]");
// [ada] [36] [] [london]
```

- `new CsvFields(ReadOnlySpan<char> line)`.
- `bool MoveNext(out ReadOnlySpan<char> field)` gives the next comma-separated field (empty fields included) and returns `true`, or returns `false` once every field has been given. An empty line has one empty field.
- No quoting rules: every comma separates.

Then write `public static class Csv` with `public static int SumColumn(string text, int column)` that adds up the integer in the given column (0-based) of every line of `text` (lines separated by `\n`, an optional `\r` before it ignored, blank lines skipped) using `CsvFields` and `int.Parse` on spans. A missing column throws `FormatException`.

starter.Solution.cs:
public ref struct CsvFields
{
    public CsvFields(ReadOnlySpan<char> line) { }

    public bool MoveNext(out ReadOnlySpan<char> field)
    {
        field = default;
        return false;
    }
}

public static class Csv
{
    public static int SumColumn(string text, int column) => 0;
}

solution.Solution.cs:
public ref struct CsvFields
{
    private ReadOnlySpan<char> _rest;
    private bool _done;

    public CsvFields(ReadOnlySpan<char> line)
    {
        _rest = line;
        _done = false;
    }

    public bool MoveNext(out ReadOnlySpan<char> field)
    {
        if (_done)
        {
            field = default;
            return false;
        }
        int comma = _rest.IndexOf(',');
        if (comma < 0)
        {
            field = _rest;
            _done = true;
        }
        else
        {
            field = _rest[..comma];
            _rest = _rest[(comma + 1)..];
        }
        return true;
    }
}

public static class Csv
{
    public static int SumColumn(string text, int column)
    {
        int total = 0;
        ReadOnlySpan<char> rest = text;
        while (rest.Length > 0)
        {
            int newline = rest.IndexOf('\n');
            ReadOnlySpan<char> line = newline < 0 ? rest : rest[..newline];
            rest = newline < 0 ? ReadOnlySpan<char>.Empty : rest[(newline + 1)..];
            if (line.EndsWith("\r")) line = line[..^1];
            if (line.IsWhiteSpace()) continue;

            var fields = new CsvFields(line);
            int index = 0;
            bool found = false;
            while (fields.MoveNext(out var field))
            {
                if (index++ == column)
                {
                    total += int.Parse(field);
                    found = true;
                    break;
                }
            }
            if (!found) throw new FormatException($"a line has no column {column}");
        }
        return total;
    }
}

unitTests:
Test("fields", () =>
{
    var seen = new List<string>();
    var fields = new CsvFields("ada,36,,london");
    while (fields.MoveNext(out var f)) seen.Add(f.ToString());
    CheckEq(seen, new[] { "ada", "36", "", "london" });

    var one = new List<string>();
    var empty = new CsvFields("");
    while (empty.MoveNext(out var f)) one.Add(f.ToString());
    CheckEq(one, new[] { "" });
});

Test("sum a column", () =>
{
    CheckEq(Csv.SumColumn("a,1,x\r\nb,2,y\n\nc,39,z\n", 1), 42);
    CheckEq(Csv.SumColumn("", 0), 0);
    CheckThrows<FormatException>(() => Csv.SumColumn("a,1\nb\n", 1));
});

